// EnemyData.cs
[System.Serializable]
public class EnemyData
{
    public string id;
    public string displayName;
    public int hp;
    public float speed;
    public int damage;
    public int expReward;
}

[System.Serializable]
public class EnemyDatabase { public EnemyData[] enemies; }

// EnemyRegistry.cs
public class EnemyRegistry : MonoBehaviour
{
    // El Dictionary se puebla en runtime desde JSON
    private Dictionary<string, EnemyData> registry = new Dictionary<string, EnemyData>();

    void Awake()
    {
        // 1. Cargar el JSON
        TextAsset file = Resources.Load<TextAsset>("enemies");
        EnemyDatabase db = JsonUtility.FromJson<EnemyDatabase>(file.text);

        // 2. Poblar el Dictionary usando el id como key
        foreach (EnemyData enemy in db.enemies)
        {
            registry[enemy.id] = enemy; // key = "goblin", "orc", etc.
        }
    }

    // 3. Acceso O(1) por ID
    public EnemyData Get(string id)
    {
        registry.TryGetValue(id, out EnemyData data);
        return data; // null si no existe
    }
}

// ── Item Database ──
public class ItemDatabase : MonoBehaviour
{
    private Dictionary<string, ItemData> items = new Dictionary<string, ItemData>();

    public void LoadFrom(ItemData[] data)
    {
        foreach (var item in data)
            items[item.id] = item;
    }

    // Acceso O(1): obtener datos de un item por ID
    public ItemData GetItem(string id) =>
        items.TryGetValue(id, out var data) ? data : null;

    // Verificar si existe antes de acceder
    public bool Exists(string id) => items.ContainsKey(id);
}

