}

public class DialogueSystem
{
    private Dictionary<string, DialogueData> dialogues
        = new Dictionary<string, DialogueData>();

    public void LoadDialogues(DialogueData[] data)
    {
        dialogues.Clear();
        foreach (var d in data)
            dialogues[d.npcId] = d;
    }

    public string[] GetLines(string npcId)
    {
        return dialogues.TryGetValue(npcId, out var d)
            ? d.lines
            : new string[0];
    }
}

